package com.sellerflow.live;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Which QR in the camera view is "the" sticker — the Android mirror of src/lib/qrCentrePick.ts
 * (and of QrCentrePick in the iOS SellerFlowScannerPlugin.swift). Pure: no Android classes, so
 * QrCentrePickTest runs it against the SAME shared examples (QrCentrePickCases, generated by
 * scripts/gen-qr-pick-cases.mjs).
 *
 *  1. Only a QR whose centre is inside the square frame counts (edges count as inside).
 *  2. The same text twice is one QR — its nearest copy counts.
 *  3. One QR → it wins. More → the nearest wins only when nearer than the next different QR by
 *     at least MARGIN × the frame's side; else a tie ("Point at one QR").
 *  4. Read only when the same winner comes out of FRAMES frames in a row.
 */
final class QrCentrePick {
    static final double MARGIN = 0.15;
    static final int FRAMES = 2;

    static final class Hit {
        final String text;
        final double cx;
        final double cy;

        Hit(String text, double cx, double cy) {
            this.text = text;
            this.cx = cx;
            this.cy = cy;
        }
    }

    /** kind = "none" | "one" | "tie"; text only for "one". */
    static final class Verdict {
        static final Verdict NONE = new Verdict("none", null);
        static final Verdict TIE = new Verdict("tie", null);
        final String kind;
        final String text;

        private Verdict(String kind, String text) {
            this.kind = kind;
            this.text = text;
        }

        static Verdict one(String text) {
            return new Verdict("one", text);
        }

        String word() {
            return "one".equals(kind) ? "one:" + text : kind;
        }
    }

    static final class Streak {
        final String text;
        final int count;

        Streak(String text, int count) {
            this.text = text;
            this.count = count;
        }
    }

    static final class Step {
        final Streak streak;
        final String read;
        final boolean tie;

        Step(Streak streak, String read, boolean tie) {
            this.streak = streak;
            this.read = read;
            this.tie = tie;
        }
    }

    private static boolean finite(double d) {
        return !Double.isNaN(d) && !Double.isInfinite(d);
    }

    /** One camera frame → none / one winner / tie. */
    static Verdict pick(Hit[] hits, double frameCx, double frameCy, double side) {
        if (!finite(frameCx) || !finite(frameCy) || !finite(side) || side <= 0) return Verdict.NONE;
        double half = side / 2;
        Map<String, Double> best = new HashMap<>();
        List<String> order = new ArrayList<>();
        if (hits != null) {
            for (Hit h : hits) {
                if (h == null || h.text == null || h.text.isEmpty() || !finite(h.cx) || !finite(h.cy)) continue;
                double dx = h.cx - frameCx;
                double dy = h.cy - frameCy;
                if (Math.abs(dx) > half || Math.abs(dy) > half) continue;
                double d = Math.hypot(dx, dy);
                Double prev = best.get(h.text);
                if (prev == null) order.add(h.text);
                if (prev == null || d < prev) best.put(h.text, d);
            }
        }
        if (best.isEmpty()) return Verdict.NONE;
        String first = null;
        double d1 = Double.MAX_VALUE;
        for (String t : order) {
            double d = best.get(t);
            if (d < d1) {
                d1 = d;
                first = t;
            }
        }
        if (best.size() == 1) return Verdict.one(first);
        double d2 = Double.MAX_VALUE;
        for (String t : order) {
            if (t.equals(first)) continue;
            d2 = Math.min(d2, best.get(t));
        }
        return d2 - d1 >= MARGIN * side ? Verdict.one(first) : Verdict.TIE;
    }

    /** The next frame's verdict → new streak, text to read (or null), show "Point at one QR". */
    static Step step(Streak prev, Verdict v) {
        if (v == null || "none".equals(v.kind)) return new Step(null, null, false);
        if ("tie".equals(v.kind)) return new Step(null, null, true);
        int count = prev != null && prev.text.equals(v.text) ? prev.count + 1 : 1;
        return new Step(new Streak(v.text, count), count >= FRAMES ? v.text : null, false);
    }

    /**
     * A point of the analysed camera image (upright: rotation already applied, imgW × imgH) → the
     * on-screen view, for a preview that FILLS the view and is centred (PreviewView FILL_CENTER).
     * mirror = the front camera (its preview is shown mirrored).
     */
    static double[] mapToView(double x, double y, double imgW, double imgH, double viewW, double viewH, boolean mirror) {
        if (imgW <= 0 || imgH <= 0 || viewW <= 0 || viewH <= 0) return new double[] { Double.NaN, Double.NaN };
        double scale = Math.max(viewW / imgW, viewH / imgH);
        double offX = (viewW - imgW * scale) / 2;
        double offY = (viewH - imgH * scale) / 2;
        double vx = x * scale + offX;
        double vy = y * scale + offY;
        if (mirror) vx = viewW - vx;
        return new double[] { vx, vy };
    }

    private QrCentrePick() {}
}
